using System;
using System.Collections.Generic;
using System.Reflection;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel.Connectors.Google.Core;
using Xunit;
using Moq;

namespace Microsoft.SemanticKernel.Connectors.Google.Core.Tests
{
    public class GeminiChatCompletionClientTests
    {
        private static object CreateMetadata(int promptTokens, int completionTokens, int totalTokens)
        {
            // Create a minimal anonymous type with the needed properties
            return new
            {
                PromptTokenCount = promptTokens,
                CandidatesTokenCount = completionTokens,
                TotalTokenCount = totalTokens
            };
        }

        private static object CreateChatMessageContent(object metadata)
        {
            // Create a minimal anonymous type with Metadata property
            return new
            {
                Metadata = metadata
            };
        }

        [Fact]
        public void LogUsage_LogsInformation_WhenMetadataHasTokenCounts()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            loggerMock.Setup(l => l.IsEnabled(LogLevel.Information)).Returns(true);

            // Create instance of GeminiChatCompletionClient via reflection (internal class)
            var clientType = typeof(GeminiChatCompletionClient);
            var ctor = clientType.GetConstructor(
                BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public,
                null,
                new Type[] { typeof(System.Net.Http.HttpClient), typeof(string), typeof(string), typeof(object), typeof(ILogger) },
                null);

            // The above constructor signature is not known exactly, so fallback to any constructor with ILogger last param
            if (ctor == null)
            {
                foreach (var c in clientType.GetConstructors(BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public))
                {
                    var parameters = c.GetParameters();
                    if (parameters.Length > 0 && parameters[^1].ParameterType == typeof(ILogger))
                    {
                        ctor = c;
                        break;
                    }
                }
            }
            Assert.NotNull(ctor);

            // Provide dummy parameters for constructor except logger
            var parametersCtor = ctor.GetParameters();
            var args = new object[parametersCtor.Length];
            for (int i = 0; i < args.Length - 1; i++)
            {
                var pType = parametersCtor[i].ParameterType;
                if (pType == typeof(string)) args[i] = "test";
                else if (pType == typeof(System.Net.Http.HttpClient)) args[i] = new System.Net.Http.HttpClient();
                else if (pType == typeof(Func<ValueTask<string>>)) args[i] = new Func<ValueTask<string>>(() => new ValueTask<string>("token"));
                else args[i] = null;
            }
            args[^1] = loggerMock.Object;

            var client = ctor.Invoke(args);

            // Create metadata and chat message content with reflection
            var metadata = CreateMetadata(10, 20, 30);
            var chatMessageContent = CreateChatMessageContent(metadata);
            var listType = typeof(List<>).MakeGenericType(chatMessageContent.GetType());
            var chatMessageContents = Activator.CreateInstance(listType) as System.Collections.IList;
            chatMessageContents.Add(chatMessageContent);

            // Act
            var logUsageMethod = clientType.GetMethod("LogUsage", BindingFlags.NonPublic | BindingFlags.Instance);
            Assert.NotNull(logUsageMethod);
            logUsageMethod.Invoke(client, new object[] { chatMessageContents });

            // Assert
            loggerMock.Verify(l => l.Log(
                LogLevel.Information,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString()!.Contains("Prompt tokens: 10. Completion tokens: 20. Total tokens: 30.")),
                null,
                It.IsAny<Func<It.IsAnyType, Exception?, string>>()),
                Times.Once);
        }
    }
}
